USE `NUERS`;
DELIMITER $$
CREATE DEFINER=`nuers`@`%` TRIGGER ledger_sales_payload_insert AFTER INSERT ON eis_invoice_payloads FOR EACH ROW BEGIN INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'receipt',NEW.receipt_id,1 FROM DUAL WHERE NEW.receipt_id IS NOT NULL ON DUPLICATE KEY UPDATE generation=generation+1; INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'invoice',NEW.source_document_id,1 FROM DUAL WHERE NEW.source_document_id IS NOT NULL AND NEW.source_document_type='invoice' ON DUPLICATE KEY UPDATE generation=generation+1; END$$
CREATE DEFINER=`nuers`@`%` TRIGGER ledger_sales_payload_update AFTER UPDATE ON eis_invoice_payloads FOR EACH ROW BEGIN INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'receipt',OLD.receipt_id,1 FROM DUAL WHERE OLD.receipt_id IS NOT NULL ON DUPLICATE KEY UPDATE generation=generation+1; INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'invoice',OLD.source_document_id,1 FROM DUAL WHERE OLD.source_document_id IS NOT NULL AND OLD.source_document_type='invoice' ON DUPLICATE KEY UPDATE generation=generation+1; INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'receipt',NEW.receipt_id,1 FROM DUAL WHERE NEW.receipt_id IS NOT NULL ON DUPLICATE KEY UPDATE generation=generation+1; INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'invoice',NEW.source_document_id,1 FROM DUAL WHERE NEW.source_document_id IS NOT NULL AND NEW.source_document_type='invoice' ON DUPLICATE KEY UPDATE generation=generation+1; END$$
CREATE DEFINER=`nuers`@`%` TRIGGER ledger_sales_payload_delete AFTER DELETE ON eis_invoice_payloads FOR EACH ROW BEGIN INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'receipt',OLD.receipt_id,1 FROM DUAL WHERE OLD.receipt_id IS NOT NULL ON DUPLICATE KEY UPDATE generation=generation+1; INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'invoice',OLD.source_document_id,1 FROM DUAL WHERE OLD.source_document_id IS NOT NULL AND OLD.source_document_type='invoice' ON DUPLICATE KEY UPDATE generation=generation+1; END$$
CREATE DEFINER=`nuers`@`%` TRIGGER ledger_sales_transmission_insert AFTER INSERT ON eis_transmissions FOR EACH ROW BEGIN INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'receipt',p.receipt_id,1 FROM eis_invoice_payloads p WHERE p.id=NEW.payload_id AND p.merchant_id=NEW.merchant_id AND p.receipt_id IS NOT NULL ON DUPLICATE KEY UPDATE generation=generation+1; INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'invoice',p.source_document_id,1 FROM eis_invoice_payloads p WHERE p.id=NEW.payload_id AND p.merchant_id=NEW.merchant_id AND p.source_document_id IS NOT NULL AND p.source_document_type='invoice' ON DUPLICATE KEY UPDATE generation=generation+1; END$$
CREATE DEFINER=`nuers`@`%` TRIGGER ledger_sales_transmission_update AFTER UPDATE ON eis_transmissions FOR EACH ROW BEGIN INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'receipt',p.receipt_id,1 FROM eis_invoice_payloads p WHERE p.id=OLD.payload_id AND p.merchant_id=OLD.merchant_id AND p.receipt_id IS NOT NULL ON DUPLICATE KEY UPDATE generation=generation+1; INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'invoice',p.source_document_id,1 FROM eis_invoice_payloads p WHERE p.id=OLD.payload_id AND p.merchant_id=OLD.merchant_id AND p.source_document_id IS NOT NULL AND p.source_document_type='invoice' ON DUPLICATE KEY UPDATE generation=generation+1; INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'receipt',p.receipt_id,1 FROM eis_invoice_payloads p WHERE p.id=NEW.payload_id AND p.merchant_id=NEW.merchant_id AND p.receipt_id IS NOT NULL ON DUPLICATE KEY UPDATE generation=generation+1; INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'invoice',p.source_document_id,1 FROM eis_invoice_payloads p WHERE p.id=NEW.payload_id AND p.merchant_id=NEW.merchant_id AND p.source_document_id IS NOT NULL AND p.source_document_type='invoice' ON DUPLICATE KEY UPDATE generation=generation+1; END$$
CREATE DEFINER=`nuers`@`%` TRIGGER ledger_sales_transmission_delete AFTER DELETE ON eis_transmissions FOR EACH ROW BEGIN INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'receipt',p.receipt_id,1 FROM eis_invoice_payloads p WHERE p.id=OLD.payload_id AND p.merchant_id=OLD.merchant_id AND p.receipt_id IS NOT NULL ON DUPLICATE KEY UPDATE generation=generation+1; INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'invoice',p.source_document_id,1 FROM eis_invoice_payloads p WHERE p.id=OLD.payload_id AND p.merchant_id=OLD.merchant_id AND p.source_document_id IS NOT NULL AND p.source_document_type='invoice' ON DUPLICATE KEY UPDATE generation=generation+1; END$$
CREATE DEFINER=`nuers`@`%` TRIGGER ledger_sales_ack_insert AFTER INSERT ON eis_acknowledgements FOR EACH ROW BEGIN INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'receipt',p.receipt_id,1 FROM eis_transmissions t JOIN eis_invoice_payloads p ON p.id=t.payload_id AND p.merchant_id=t.merchant_id WHERE t.id=NEW.transmission_id AND p.receipt_id IS NOT NULL ON DUPLICATE KEY UPDATE generation=generation+1; INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'invoice',p.source_document_id,1 FROM eis_transmissions t JOIN eis_invoice_payloads p ON p.id=t.payload_id AND p.merchant_id=t.merchant_id WHERE t.id=NEW.transmission_id AND p.source_document_id IS NOT NULL AND p.source_document_type='invoice' ON DUPLICATE KEY UPDATE generation=generation+1; END$$
CREATE DEFINER=`nuers`@`%` TRIGGER ledger_sales_ack_update AFTER UPDATE ON eis_acknowledgements FOR EACH ROW BEGIN INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'receipt',p.receipt_id,1 FROM eis_transmissions t JOIN eis_invoice_payloads p ON p.id=t.payload_id AND p.merchant_id=t.merchant_id WHERE t.id=OLD.transmission_id AND p.receipt_id IS NOT NULL ON DUPLICATE KEY UPDATE generation=generation+1; INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'invoice',p.source_document_id,1 FROM eis_transmissions t JOIN eis_invoice_payloads p ON p.id=t.payload_id AND p.merchant_id=t.merchant_id WHERE t.id=OLD.transmission_id AND p.source_document_id IS NOT NULL AND p.source_document_type='invoice' ON DUPLICATE KEY UPDATE generation=generation+1; INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'receipt',p.receipt_id,1 FROM eis_transmissions t JOIN eis_invoice_payloads p ON p.id=t.payload_id AND p.merchant_id=t.merchant_id WHERE t.id=NEW.transmission_id AND p.receipt_id IS NOT NULL ON DUPLICATE KEY UPDATE generation=generation+1; INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'invoice',p.source_document_id,1 FROM eis_transmissions t JOIN eis_invoice_payloads p ON p.id=t.payload_id AND p.merchant_id=t.merchant_id WHERE t.id=NEW.transmission_id AND p.source_document_id IS NOT NULL AND p.source_document_type='invoice' ON DUPLICATE KEY UPDATE generation=generation+1; END$$
CREATE DEFINER=`nuers`@`%` TRIGGER ledger_sales_ack_delete AFTER DELETE ON eis_acknowledgements FOR EACH ROW BEGIN INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'receipt',p.receipt_id,1 FROM eis_transmissions t JOIN eis_invoice_payloads p ON p.id=t.payload_id AND p.merchant_id=t.merchant_id WHERE t.id=OLD.transmission_id AND p.receipt_id IS NOT NULL ON DUPLICATE KEY UPDATE generation=generation+1; INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'invoice',p.source_document_id,1 FROM eis_transmissions t JOIN eis_invoice_payloads p ON p.id=t.payload_id AND p.merchant_id=t.merchant_id WHERE t.id=OLD.transmission_id AND p.source_document_id IS NOT NULL AND p.source_document_type='invoice' ON DUPLICATE KEY UPDATE generation=generation+1; END$$
CREATE DEFINER=`nuers`@`%` TRIGGER ledger_sales_original_insert AFTER INSERT ON business_invoices FOR EACH ROW BEGIN INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'invoice',id,1 FROM business_invoices WHERE original_invoice_id=NEW.id ON DUPLICATE KEY UPDATE generation=generation+1; END$$
CREATE DEFINER=`nuers`@`%` TRIGGER ledger_sales_original_update AFTER UPDATE ON business_invoices FOR EACH ROW BEGIN INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'invoice',id,1 FROM business_invoices WHERE original_invoice_id=OLD.id ON DUPLICATE KEY UPDATE generation=generation+1; INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'invoice',id,1 FROM business_invoices WHERE original_invoice_id=NEW.id ON DUPLICATE KEY UPDATE generation=generation+1; END$$
CREATE DEFINER=`nuers`@`%` TRIGGER ledger_sales_original_delete AFTER DELETE ON business_invoices FOR EACH ROW BEGIN INSERT INTO ledger_dirty_documents (source,document_id,generation) SELECT 'invoice',id,1 FROM business_invoices WHERE original_invoice_id=OLD.id ON DUPLICATE KEY UPDATE generation=generation+1; END$$
DELIMITER ;
